<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/admin.php';
$user=admin_require_roles(['super_admin','admin','receptionist']);$db=db();$receptionist=$user['role_name']==='receptionist';
$views=['dashboard','reservations','submissions','banners','staff','campaigns','branches','users','settings'];$view=request_string($_GET,'view')?:'dashboard';if(!in_array($view,$views,true))$view='dashboard';
if($receptionist&&!in_array($view,['dashboard','reservations','submissions'],true))$view='dashboard';
$flash=admin_take_flash();$branches=$db->query('SELECT id,name FROM branches WHERE deleted_at IS NULL ORDER BY name')->fetch_all(MYSQLI_ASSOC);
