if($language==='ar'){$labels=['dashboard'=>'لوحة المعلومات','reservations'=>'الحجوزات','submissions'=>'طلبات التواصل','banners'=>'اللافتات','staff'=>'الفريق','campaigns'=>'الحملات','branches'=>'الفروع','users'=>'المستخدمون','settings'=>'إعدادات الموقع'];$roleLabels=['super_admin'=>'مشرف أعلى','admin'=>'مدير','receptionist'=>'موظف استقبال'];}
$allowed=$receptionist?['dashboard','reservations','submissions']:$views;
function admin_rows(mysqli $db,string $sql):array{return $db->query($sql)->fetch_all(MYSQLI_ASSOC);}
function admin_form(string $view,string $action,array $fields,array $row=[]):void{echo '<form class="admin-form" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';if(!empty($row['id']))echo '<input type="hidden" name="id" value="'.(int)$row['id'].'">';echo '<div class="row g-3">';foreach($fields as $field=>$meta){if($field==='is_active')continue;[$label,$type,$required]=$meta;$value=$row[$field]??'';echo '<div class="col-md-6"><label class="form-label" for="f-'.e($field).'">'.e($label).'</label>';if($type==='textarea')echo '<textarea class="form-control" id="f-'.e($field).'" name="'.e($field).'" rows="3">'.e($value).'</textarea>';else echo '<input class="form-control" id="f-'.e($field).'" type="'.e($type).'" name="'.e($field).'" value="'.e($value).'"'.($required?' required':'').'> ';echo '</div>';}if(in_array('is_active',array_keys($fields),true))echo '<div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" id="f-active" '.(($row['is_active']??1)?'checked':'').'><label class="form-check-label" for="f-active">Active</label></div></div>';echo '<div class="col-12"><button class="btn btn-primary" type="submit">Save</button></div></div></form>';}
?><!doctype html><html lang="<?=e($language)?>" dir="<?=e($isRtl?'rtl':'ltr')?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($labels[$view])?> · <?=e($siteSettings['lab_name'])?></title><link rel="icon" href="<?=e(admin_media_url((string)$siteSettings['favicon_path']))?>"><link rel="stylesheet" href="<?=asset('assets/css/bootstrap'.($isRtl?'.rtl':'').'.min.css')?>"><link rel="stylesheet" href="<?=asset('assets/css/all.min.css')?>"><link rel="stylesheet" href="<?=asset('assets/css/main.css')?>"><link rel="stylesheet" href="<?=asset('assets/css/admin.css')?>"><style>:root{<?php foreach($theme as $k=>$v):?>--<?=e(str_replace('_','-',$k))?>:<?=e($v)?>;<?php endforeach?></style></head><body class="admin-body"><div class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="index.php"><img src="<?=e(admin_media_url((string)$siteSettings['logo_path']))?>" alt=""><span><?=e($siteSettings['lab_name'])?></span></a><nav><?php foreach($allowed as $item):?><a class="admin-nav-link <?=$item===$view?'active':''?>" href="?view=<?=e($item)?>"><i class="fa-solid <?=e(['dashboard'=>'fa-gauge','reservations'=>'fa-calendar-check','submissions'=>'fa-inbox','banners'=>'fa-images','staff'=>'fa-user-doctor','campaigns'=>'fa-tags','branches'=>'fa-location-dot','users'=>'fa-users','settings'=>'fa-gear'][$item])?>"></i><?=e($labels[$item])?></a><?php endforeach?></nav><a class="admin-public-link" href="<?=e(site_url())?>"><i class="fa-solid fa-arrow-up-right-from-square"></i> <?=e($language==='ar'?'عرض الموقع':'View public site')?></a></aside><main class="admin-main"><header class="admin-topbar"><div><h1><?=e($labels[$view])?></h1><div class="text-muted small"><?=e($user['name'])?> · <?=e($roleLabels[$user['role_name']]??$user['role_name'])?></div></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary btn-sm" href="?view=<?=e($view)?>&lang=<?=$language==='ar'?'en':'ar'?>"><?=$language==='ar'?'English':'العربية'?></a><button type="button" class="btn btn-outline-secondary btn-sm" data-theme-toggle aria-label="Toggle dark mode"><i class="fa-solid fa-moon"></i></button><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-outline-secondary btn-sm"><?=e($language==='ar'?'تسجيل الخروج':'Sign out')?></button></form></div></header><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?>
<?php if($view==='dashboard'):
$branchFilter=$receptionist?' AND r.branch_id IN (SELECT branch_id FROM branch_staff WHERE user_id='.(int)$user['id'].' AND is_active=1)':'';
$counts=['reservations'=>(int)$db->query('SELECT COUNT(*) n FROM reservations r WHERE r.deleted_at IS NULL'.$branchFilter)->fetch_assoc()['n'],'pending'=>(int)$db->query("SELECT COUNT(*) n FROM reservations r WHERE r.deleted_at IS NULL AND r.status='pending'".$branchFilter)->fetch_assoc()['n'],'submissions'=>(int)$db->query('SELECT COUNT(*) n FROM form_submissions s WHERE s.deleted_at IS NULL'.($receptionist?' AND s.branch_id IN (SELECT branch_id FROM branch_staff WHERE user_id='.(int)$user['id'].' AND is_active=1)':''))->fetch_assoc()['n']];?>
<section class="admin-stats"><article><span>Reservations</span><strong><?=$counts['reservations']?></strong></article><article><span>Pending reservations</span><strong><?=$counts['pending']?></strong></article><article><span>Form submissions</span><strong><?=$counts['submissions']?></strong></article><?php if(!$receptionist):?><article><span>Active campaigns</span><strong><?= (int)$db->query('SELECT COUNT(*) n FROM campaigns WHERE is_active=1 AND deleted_at IS NULL')->fetch_assoc()['n']?></strong></article><?php endif?></section><section class="admin-panel"><h2>Recent reservations</h2><?php $sql="SELECT r.id,p.name patient,c.name campaign,b.name branch,r.status,r.created_at FROM reservations r JOIN patients p ON p.id=r.patient_id JOIN campaigns c ON c.id=r.campaign_id LEFT JOIN branches b ON b.id=r.branch_id WHERE r.deleted_at IS NULL$branchFilter ORDER BY r.created_at DESC LIMIT 8";include __DIR__.'/partials/reservation-table.php';?></section>
<?php elseif($view==='reservations'):$scope=$receptionist?' AND r.branch_id IN (SELECT branch_id FROM branch_staff WHERE user_id='.(int)$user['id'].' AND is_active=1)':'';$noteColumn=$receptionist?'r.patient_note':'r.internal_note';$rows=admin_rows($db,"SELECT r.id,p.name patient,p.phone_number,c.name campaign,b.name branch,r.reservation_date,r.reservation_time,r.status,$noteColumn AS visible_note,r.created_at FROM reservations r JOIN patients p ON p.id=r.patient_id JOIN campaigns c ON c.id=r.campaign_id LEFT JOIN branches b ON b.id=r.branch_id WHERE r.deleted_at IS NULL$scope ORDER BY r.created_at DESC LIMIT 300");?><section class="admin-panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>ID</th><th>Patient</th><th>Campaign</th><th>Branch</th><th>Schedule</th><th>Status</th><th>Notes</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=(int)$r['id']?></td><td><?=e($r['patient'])?><small class="d-block text-muted"><?=e($r['phone_number'])?></small></td><td><?=e($r['campaign'])?></td><td><?=e($r['branch']??'—')?></td><td><?=e($r['reservation_date']??'—')?> <?=e($r['reservation_time']??'')?></td><td><span class="badge text-bg-light"><?=e($r['status'])?></span></td><td><?=e($r['visible_note'])?></td><td><form class="d-flex gap-2" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reservation_status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['pending','confirmed','attended','no_show','cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($view==='submissions'):$scope=$receptionist?' AND s.branch_id IN (SELECT branch_id FROM branch_staff WHERE user_id='.(int)$user['id'].' AND is_active=1)':'';$rows=admin_rows($db,"SELECT s.*,c.name campaign,b.name branch FROM form_submissions s LEFT JOIN campaigns c ON c.id=s.campaign_id LEFT JOIN branches b ON b.id=s.branch_id WHERE s.deleted_at IS NULL$scope ORDER BY s.created_at DESC LIMIT 300");?><section class="admin-panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Contact</th><th>Campaign / branch</th><th>Message</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small class="d-block text-muted"><?=e($r['phone_number'])?></small></td><td><?=e($r['campaign']??'—')?> / <?=e($r['branch']??'—')?></td><td><?=e($r['notes'])?></td><td><?=e($r['status'])?></td><td><form method="post" action="actions.php" class="d-grid gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="submission_status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status" class="form-select form-select-sm"><?php foreach(['new','contacted','completed','cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach?></select><textarea class="form-control form-control-sm" name="notes" placeholder="Internal notes"><?=e($r['notes'])?></textarea><input class="form-control form-control-sm" name="cancelled_reason" value="<?=e($r['cancelled_reason'])?>" placeholder="Cancellation reason"><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($view==='banners'):?><section class="admin-panel"><h2>Add banner</h2><?php admin_form($view,'save_banner',['title'=>['Title','text',false],'subtitle'=>['Subtitle','text',false],'image_path'=>['Image path','text',true],'button_text'=>['Button text','text',false],'button_link'=>['Button link','text',false],'sort_order'=>['Sort order','number',false],'is_active'=>['Active','checkbox',false]]);?><hr><h2>Existing banners</h2><div class="table-responsive"><table class="table"><thead><tr><th>Title</th><th>Image</th><th>Status</th></tr></thead><tbody><?php foreach(admin_rows($db,'SELECT id,title,image_path,is_active FROM banners ORDER BY sort_order,id DESC') as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['image_path'])?></td><td><?=$r['is_active']?'Active':'Hidden'?></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($view==='staff'):?><section class="admin-panel"><h2>Add staff member</h2><?php admin_form($view,'save_staff',['name'=>['Name','text',true],'title'=>['Title','text',false],'specialty'=>['Specialty','text',false],'image_path'=>['Image path','text',false],'bio'=>['Biography','textarea',false],'sort_order'=>['Sort order','number',false],'is_active'=>['Active','checkbox',false]]);?><hr><h2>Staff list</h2><?php foreach(admin_rows($db,'SELECT name,title,specialty,is_active FROM staff WHERE deleted_at IS NULL ORDER BY sort_order,id DESC') as $r):?><div class="list-row"><strong><?=e($r['name'])?></strong> · <?=e($r['title'])?> · <?=e($r['specialty'])?> <span class="badge text-bg-light"><?=$r['is_active']?'Active':'Hidden'?></span></div><?php endforeach?></section>
