<?php elseif($view==='users'):$rows=admin_rows($db,'SELECT u.id,u.name,u.email,u.phone_number,u.is_active,r.name role_name,GROUP_CONCAT(b.name ORDER BY b.name SEPARATOR ", ") branches,GROUP_CONCAT(bs.branch_id ORDER BY b.name SEPARATOR ",") branch_ids FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN branch_staff bs ON bs.user_id=u.id AND bs.is_active=1 LEFT JOIN branches b ON b.id=bs.branch_id WHERE u.deleted_at IS NULL GROUP BY u.id ORDER BY r.id,u.name');?><section class="admin-panel"><h2>Create account</h2><?php if($user['role_name']==='super_admin'):?><form class="admin-form" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_user"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" name="email" type="email"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone_number"></div><div class="col-md-6"><label class="form-label">Temporary password (12+ chars)</label><input class="form-control" name="password" type="password" minlength="12" required></div><div class="col-md-6"><label class="form-label">Role</label><select class="form-select" name="role_name"><?php foreach($roleLabels as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Receptionist branches</label><select class="form-select" name="branch_ids[]" multiple><?php foreach($branches as $b):?><option value="<?=(int)$b['id']?>"><?=e($b['name'])?></option><?php endforeach?></select></div><div class="col-12"><div class="form-check"><input class="form-check-input" name="is_active" type="checkbox" checked><label class="form-check-label">Active</label></div></div><div class="col-12"><button class="btn btn-primary">Create user</button></div></div></form><?php else:?><p class="text-muted">Admins cannot create accounts, change roles or edit branch assignments.</p><?php endif?><hr><h2>Accounts</h2><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Contact</th><th>Role</th><th>Branches</th><th>Active</th><th>Edit</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email']??$r['phone_number'])?></td><td><?=e($roleLabels[$r['role_name']]??$r['role_name'])?></td><td><?=e($r['branches'])?></td><td><?=$r['is_active']?'Yes':'No'?></td><td><details><summary>Edit</summary><form class="vstack gap-2 mt-2" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_user"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input class="form-control form-control-sm" name="name" value="<?=e($r['name'])?>" required><input class="form-control form-control-sm" name="email" type="email" value="<?=e($r['email'])?>" placeholder="Email"><input class="form-control form-control-sm" name="phone_number" value="<?=e($r['phone_number'])?>" placeholder="Phone"><input class="form-control form-control-sm" type="password" name="password" minlength="12" placeholder="New password (optional)"><?php if($user['role_name']==='super_admin'):?><select class="form-select form-select-sm" name="role_name"><?php foreach($roleLabels as $k=>$v):?><option value="<?=e($k)?>" <?=$r['role_name']===$k?'selected':''?>><?=e($v)?></option><?php endforeach?></select><select class="form-select form-select-sm" name="branch_ids[]" multiple><?php foreach($branches as $b):?><option value="<?=(int)$b['id']?>" <?=in_array((int)$b['id'],array_map('intval',explode(',',(string)$r['branch_ids'])),true)?'selected':''?>><?=e($b['name'])?></option><?php endforeach?></select><?php endif?><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?=$r['is_active']?'checked':''?>> Active</label><button class="btn btn-sm btn-primary">Save account</button></form></details></td></tr><?php endforeach?></tbody></table></div></section>
<?php elseif($view==='settings'):$settings=site_settings();$themeNow=theme_settings();?><section class="admin-panel"><h2>Brand and contact information</h2><form class="admin-form" method="post" action="actions.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_settings"><div class="row g-3"><?php foreach(['lab_name'=>'Site name','about'=>'About','logo_path'=>'Logo path','favicon_path'=>'Favicon path','phone_number'=>'Phone','whatsapp_number'=>'WhatsApp','email'=>'Email','address'=>'Address','google_map_link'=>'Map URL','working_hours'=>'Working hours','facebook_url'=>'Facebook URL','instagram_url'=>'Instagram URL','youtube_url'=>'YouTube URL','tiktok_url'=>'TikTok URL'] as $key=>$label):?><div class="col-md-6"><label class="form-label"><?=e($label)?></label><?php if($key==='about'):?><textarea class="form-control" name="<?=e($key)?>"><?=e($settings[$key])?></textarea><?php else:?><input class="form-control" name="<?=e($key)?>" value="<?=e($settings[$key])?>"><?php endif?></div><?php endforeach?></div><hr><h2>Light and dark theme colors</h2><div class="row g-3"><?php foreach(['primary'=>'Primary','secondary'=>'Secondary','accent'=>'Accent','background'=>'Background','surface'=>'Surface','text'=>'Text'] as $token=>$label):foreach(['light'=>'Light','dark'=>'Dark'] as $mode=>$modeLabel):$key=$token.'_'.$mode;?><div class="col-md-2"><label class="form-label"><?=e($label.' · '.$modeLabel)?></label><input class="form-control form-control-color w-100" type="color" name="<?=e($key)?>" value="<?=e($themeNow[$key])?>"></div><?php endforeach;endforeach?></div><div class="mt-3"><button class="btn btn-primary">Save site settings</button></div></form></section><?php endif?></main></div><script src="<?=asset('assets/js/bootstrap.bundle.min.js')?>"></script><script src="<?=asset('assets/js/main.js')?>"></script></body></html>
